/**
 * The offline airport table: code to city, country, zone and position.
 *
 * A departure time is local to its airport, so turning one into an instant
 * needs the airport's zone, and resolving "JFK" to New York is what lets a
 * card speak in words a person recognizes. The table ships with the app like
 * every other asset and nothing is ever looked up over the network.
 * Generated by tools/build-airports.mjs from public datasets; loaded lazily
 * so the main bundle stays lean.
 */

/** A point on the globe, in degrees. */
export interface LatLon {
  lat: number;
  lon: number;
}

export interface Airport extends LatLon {
  code: string;
  city: string;
  country: string;
  zone: string;
}

type Row = [code: string, city: string, country: string, zone: string, lat: number, lon: number];

let tablePromise: Promise<Map<string, Airport>> | null = null;

function table(): Promise<Map<string, Airport>> {
  if (!tablePromise) {
    tablePromise = import("./tables/airports.json").then((mod) => {
      const rows = (mod.default ?? mod) as Row[];
      const map = new Map<string, Airport>();
      for (const [code, city, country, zone, lat, lon] of rows) {
        map.set(code, { code, city, country, zone, lat, lon });
      }
      return map;
    });
  }
  return tablePromise;
}

/** The airport a code names, or null for one the table does not know. */
export async function lookupAirport(code: string): Promise<Airport | null> {
  if (!/^[A-Za-z]{3}$/.test(code)) {
    return null;
  }
  return (await table()).get(code.toUpperCase()) ?? null;
}

/** The first airport (by code) serving a city, or null when none does. */
/** A city's name without the district the table adds: "Sydney (Mascot)" is Sydney. */
export function plainCity(name: string): string {
  return name.replace(/\s*\([^)]*\)\s*$/, "").trim();
}

/**
 * Where a city is, as far as its name alone can say: its zone and country
 * when every airport of that name agrees, and its airport code only when
 * there is just one. "Sydney" names an airport in Australia and one in
 * Canada, so it says nothing; "London" has several airports and one zone.
 */
export async function placeForCity(city: string): Promise<{ zone: string; country: string; code?: string } | null> {
  const wanted = plainCity(city).toLowerCase();
  const named = [...(await table()).values()].filter((airport) => plainCity(airport.city).toLowerCase() === wanted);
  const first = named[0];
  if (!first || named.some((airport) => airport.zone !== first.zone || airport.country !== first.country)) {
    return null;
  }
  return { zone: first.zone, country: first.country, ...(named.length === 1 ? { code: first.code } : {}) };
}

export async function airportForCity(city: string): Promise<Airport | null> {
  const wanted = city.trim().toLowerCase();
  for (const airport of (await table()).values()) {
    if (airport.city.toLowerCase() === wanted) {
      return airport;
    }
  }
  return null;
}
